import apiClient from './client'

export interface LoginResponse {
  access_token: string
  token_type: string
  expires_in: number
}

export interface UserInfo {
  id: number
  username: string
  is_active: boolean
  created_at: string
  role: 'admin' | 'viewer'
}

export interface PasswordResetRequest {
  username: string
}

export interface PasswordResetConfirm {
  token: string
  new_password: string
}

export async function login(username: string, password: string): Promise<LoginResponse> {
  const params = new URLSearchParams()
  params.append('username', username)
  params.append('password', password)
  const response = await apiClient.post<LoginResponse>('/v1/auth/login', params, {
    headers: {
      'Content-Type': 'application/x-www-form-urlencoded',
    },
  })
  return response.data
}

export async function logout(): Promise<{ message: string }> {
  const response = await apiClient.post('/v1/auth/logout')
  return response.data
}

export async function getMe(): Promise<UserInfo> {
  const response = await apiClient.get<UserInfo>('/v1/auth/me')
  return response.data
}

export async function requestPasswordReset(username: string): Promise<{ message: string }> {
  const response = await apiClient.post<{ message: string }>('/v1/auth/password-reset/request', {
    username,
  })
  return response.data
}

export async function confirmPasswordReset(token: string, newPassword: string): Promise<{ message: string }> {
  const response = await apiClient.post<{ message: string }>('/v1/auth/password-reset/confirm', {
    token,
    new_password: newPassword,
  })
  return response.data
}
